    if(t.includes('slope')||t.includes('rate of change'))return q('Current unit focus','What is the slope through (1, 3) and (3, 7)?',2,'Slope = change in y ÷ change in x = (7 − 3) ÷ (3 − 1) = 2.',['2','4','1/2']);
    if(t.includes('linear model'))return q('Current unit focus','For y = 2x + 3, what is y when x = 4?',11,'Substitute 4 for x: 2(4) + 3 = 11.',['11','9','14']);
    if(t.includes('function'))return q('Current unit focus','Which relation is a function?','Each input has exactly one output.','A function assigns one output to every input.',['Each input has exactly one output.','One input has three different outputs.','Inputs cannot be numbers.']);
