    if(t.includes('real number'))return q('Current unit focus','Between which two whole numbers is √50?','7 and 8','49 < 50 < 64, so 7 < √50 < 8.',['7 and 8','6 and 7','8 and 9']);
    if(t.includes('circle'))return q('Current unit focus','Using π ≈ 3.14, what is the circumference of a circle with diameter 8?',25.12,'Circumference = πd = 3.14 × 8.',['25.12','50.24','12.56']);
    if(t.includes('transform'))return q('Current unit focus','A point (2, 3) is translated 4 units right. What is its image?','(6, 3)','Add 4 to the x-coordinate and keep the y-coordinate unchanged.',['(6, 3)','(2, 7)','(-2, 3)']);
    if(t.includes('similar')||t.includes('congruence'))return q('Current unit focus','A dilation has scale factor 2. A side of length 5 becomes what length?',10,'Multiply the original length by the scale factor.',['10','7','2.5']);
    if(t.includes('scale drawing'))return q('Current unit focus','On a map, 1 cm represents 4 km. What distance does 6 cm represent?',24,'Multiply 6 by the scale rate of 4 km per centimeter.',['24','10','1.5']);
    if(t.includes('probability'))return q('Current unit focus','A bag has 3 red and 2 blue counters. What is the probability of choosing red?','3/5','There are 3 favorable outcomes out of 5 equally likely counters.',['3/5','2/5','3/2']);
    if(t.includes('sampling'))return q('Current unit focus','Which method is most likely to produce a representative school survey?','Randomly select students from every grade.','A broad random sample reduces selection bias.',['Randomly select students from every grade.','Ask only one sports team.','Ask only the first five students at lunch.']);
    if(t.includes('bivariate')||t.includes('scatter'))return q('Current unit focus','Points in a scatter plot rise from left to right. What association is shown?','positive association','As one variable increases, the other tends to increase.',['positive association','negative association','no variables']);
    if(t.includes('statistics')||t.includes('data')||t.includes('line plot'))return q('Current unit focus','What is the range of 4, 7, 7, 12?',8,'Range = greatest value − least value = 12 − 4.',['8','7','30']);
    if(t.includes('integer')||t.includes('rational-number'))return q('Current unit focus','Evaluate −6 + 9.',3,'Start at −6 and move 9 units right.',['3','-15','-3']);
    if(t.includes('percent'))return q('Current unit focus','A $40 item is discounted 25%. What is the discount?','$10','Twenty-five percent is one fourth, and one fourth of $40 is $10.',['$10','$15','$30']);
    if(t.includes('ratio')||t.includes('proportional'))return q('Current unit focus','Three notebooks cost $6 at a constant rate. What do five notebooks cost?','$10','The unit price is $2, so five cost 5 × $2.',['$10','$8','$30']);
    if(t.includes('inequal'))return q('Current unit focus','Solve x + 4 < 11.','x < 7','Subtract 4 from both sides and keep the inequality direction.',['x < 7','x > 7','x = 15']);
    if(t.includes('equation'))return q('Current unit focus',g>=8?'Solve 3x + 4 = x + 12.':'Solve 3x + 4 = 19.',g>=8?4:5,g>=8?'Subtract x and 4: 2x = 8, so x = 4.':'Subtract 4, then divide 15 by 3.',g>=8?['4','8','2']:['5','7','45']);
    if(t.includes('expression')||t.includes('numerical'))return q('Current unit focus','Which expression is equivalent to 3(x + 2)?','3x + 6','Use the distributive property: multiply both terms by 3.',['3x + 6','3x + 2','x + 6']);
