    if(t.includes('fraction multiplication'))return q('Current unit focus','What is 2/3 of 12?',8,'Divide 12 into 3 equal groups, then take 2 groups: 8.',['8','18','6']);
    if(t.includes('fraction addition')||t.includes('fraction operation'))return q('Current unit focus','What is 3/8 + 2/8?','5/8','Add the numerators because the equal-sized parts have the same denominator.',['5/8','5/16','1/8']);
