    if(g>=5)qs.push(q('Ratios and percent',`What is ${percent}% of ${base}?`,base*percent/100,`${percent}% means ${percent} out of 100. Multiply ${base} by ${percent/100}.`,distract(base*percent/100)));
    else qs.push(q('Number line',`Start at ${n}. Move ${m} steps right. Where do you land?`,n+m,'Moving right increases the number.',distract(n+m),{visual:{kind:'line',min:0,max:Math.min(20,n+m+3),from:n,delta:m}}));
    if(g>=6)qs.push(q('Integers',`The temperature is ${temp}°C and rises ${rise}°. What is the new temperature?`,temp+rise,'A rise adds a positive number to the starting temperature.',[temp-rise,rise-temp,Math.abs(temp)+rise]));
    else qs.push(q('Patterns',`Continue the pattern: ${n}, ${n+m}, ${n+2*m}, __`,n+3*m,`The rule adds ${m} each time.`,distract(n+3*m)));
    const unknown=3+r(12),constant=4+r(15),result=unknown*m+constant;
    qs.push(q('Expressions and equations',g>=6?`Solve ${m}x + ${constant} = ${result}. What is x?`:`Find the missing number: ${m} × __ + ${constant} = ${result}.`,unknown,`Subtract ${constant}, then divide by ${m}.`,distract(unknown)));
